  ('1505 Series 32mm OD Counterbored Pattern Spacer (6mm Length)', '1505-0032-0060', null, 'goBILDA', null, true, 'https://www.gobilda.com/1505-series-32mm-od-counterbored-pattern-spacer-6mm-length/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/737/images/4203/1505-0032-0060_Ang1__55522__54663.1701992128.386.513.jpg?c=1', 'STRUCTURE / Pattern Spacers', 'gobilda'),
