  ('1516 Series 8mm REX® Standoff (M4 x 0.7mm Threads, 192mm Length) - 4 Pack', '1516-4008-1920', 'The 192mm length, M4-threaded, 8mm REX® Standoff provides clearance, adjusts distances between parallel parts, and reinforces structures. You can also use its threaded holes to mount other parts to your builds! And thanks to its 8mm REX® profile measuring 7mm flat-to-flat like a hex nut, you can hold it with a 7mm wrench during assembly and disassembly.', 'goBILDA', null, true, 'https://www.gobilda.com/1516-series-8mm-rex-standoff-m4-x-0-7mm-threads-192mm-length-4-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1840/images/9920/1516-4008-1920__95096__01785.1701993943.386.513.jpg?c=1', 'MOTION / Shafting & Tubing / Aluminum REX® Shafting', 'gobilda'),
  ('1516 Series 8mm REX® Standoff (M4 x 0.7mm Threads, 216mm Length) - 4 Pack', '1516-4008-2160', 'The 216mm length, M4-threaded, 8mm REX® Standoff provides clearance, adjusts distances between parallel parts, and reinforces structures. You can also use its threaded holes to mount other parts to your builds! And thanks to its 8mm REX® profile measuring 7mm flat-to-flat like a hex nut, you can hold it with a 7mm wrench during assembly and disassembly.', 'goBILDA', null, true, 'https://www.gobilda.com/1516-series-8mm-rex-standoff-m4-x-0-7mm-threads-216mm-length-4-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1843/images/9932/1516-4008-2160__94168__74990.1701993947.386.513.jpg?c=1', 'MOTION / Shafting & Tubing / Aluminum REX® Shafting', 'gobilda'),
  ('1516 Series 8mm REX® Standoff (M4 x 0.7mm Threads, 240mm Length) - 4 Pack', '1516-4008-2400', 'The 240mm length, M4-threaded, 8mm REX® Standoff provides clearance, adjusts distances between parallel parts, and reinforces structures. You can also use its threaded holes to mount other parts to your builds! And thanks to its 8mm REX™ profile measuring 7mm flat-to-flat like a hex nut, you can hold it with a 7mm wrench during assembly and disassembly.', 'goBILDA', null, true, 'https://www.gobilda.com/1516-series-8mm-rex-standoff-m4-x-0-7mm-threads-240mm-length-4-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1861/images/10026/1516-4008-2400__79277__71936.1701993973.386.513.jpg?c=1', 'MOTION / Shafting & Tubing / Aluminum REX® Shafting', 'gobilda'),
  ('1516 Series 8mm REX® Standoff (M4 x 0.7mm Threads, 264mm Length) - 4 Pack', '1516-4008-2640', 'The 264mm length, M4-threaded, 8mm REX® Standoff provides clearance, adjusts distances between parallel parts, and reinforces structures. You can also use its threaded holes to mount other parts to your builds! And thanks to its 8mm REX™ profile measuring 7mm flat-to-flat like a hex nut, you can hold it with a 7mm wrench during assembly and disassembly.', 'goBILDA', null, true, 'https://www.gobilda.com/1516-series-8mm-rex-standoff-m4-x-0-7mm-threads-264mm-length-4-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1854/images/9986/1516-4008-2640__96387__57043.1701993962.386.513.jpg?c=1', 'MOTION / Shafting & Tubing / Aluminum REX® Shafting', 'gobilda'),
  ('1516 Series 8mm REX® Standoff (M4 x 0.7mm Threads, 288mm Length) - 4 Pack', '1516-4008-2880', 'The 288mm length, M4-threaded, 8mm REX® Standoff provides clearance, adjusts distances between parallel parts, and reinforces structures. You can also use its threaded holes to mount other parts to your builds! And thanks to its 8mm REX® profile measuring 7mm flat-to-flat like a hex nut, you can hold it with a 7mm wrench during assembly and disassembly.', 'goBILDA', null, true, 'https://www.gobilda.com/1516-series-8mm-rex-standoff-m4-x-0-7mm-threads-288mm-length-4-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1852/images/9975/1516-4008-2880__77226__53540.1701993959.386.513.jpg?c=1', 'MOTION / Shafting & Tubing / Aluminum REX® Shafting', 'gobilda'),
  ('1517 Series Counterbored Pattern Spacer (32mm Bore, 8mm Length)', '1517-0032-0080', 'This Counterbored Pattern Spacer has a length of 8mm and provides thru-holes and threaded holes on the 32mm Pattern. When fastened down using the thru-holes, the threaded holes provide a convenient mounting point for the next component in your assembly. The counterbore on the thru-holes allow the screw heads to be flush with or below the top face. The 32mm bore allows 32mm OD tubing or goTUBE to pass thru. The underside has a bearing recess which allows it to capture the 1601-1032-0012 12mm…', 'goBILDA', null, true, 'https://www.gobilda.com/1517-series-counterbored-pattern-spacer-32mm-bore-8mm-length/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1440/images/7140/1517-0032-0080__82526__56377.1701993072.386.513.jpg?c=1', 'STRUCTURE / Pattern Spacers', 'gobilda'),
  ('goTUBE Endcap (14mm Bore, 36mm OD, 4mm Thick) - 4 Pack', '1519-0014-0400', 'This goTUBE Endcap bolts to the end of a piece of goTUBE. It provides a simple, light, and cost-effect method of helping you axially constrain goTUBE in a motion assembly. Its outer diameter is sized to contact the inner race of a 32mm bore bearing.', 'goBILDA', null, true, 'https://www.gobilda.com/gotube-endcap-14mm-bore-36mm-od-4mm-thick-4-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1456/images/7270/1519-0014-0400__41622__08104.1701993112.386.513.jpg?c=1', null, 'gobilda'),
  ('8mm REX® Plastic Spacer (12mm REX® OD, 8mm Length) - 12 Pack', '1520-4012-0080', 'This 8mm length, 8mm REX® bore spacer is designed for sliding onto an 8mm REX® shaft to create space between parts. Your choice of spacer length can ensure the correct alignment of drive components, such as gears and sprockets, as well as axially restrain components (such as bearings) to provide for a well-spaced and solid build!', 'goBILDA', null, true, 'https://www.gobilda.com/8mm-rex-plastic-spacer-12mm-rex-od-8mm-length-12-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1648/images/8622/1520-4012-0080__86118__74191.1701993526.386.513.jpg?c=1', 'MOTION / Shaft Spacers & Shims', 'gobilda'),
  ('8mm REX® Plastic Spacer (12mm REX OD, 12mm Length) - 12 Pack', '1520-4012-0120', 'This 12mm length, 8mm REX® bore spacer is designed for sliding onto an 8mm REX® shaft to create space between parts. Your choice of spacer length can ensure the correct alignment of drive components, such as gears and sprockets, as well as axially restrain components (such as bearings) to provide for a well-spaced and solid build!', 'goBILDA', null, true, 'https://www.gobilda.com/8mm-rex-plastic-spacer-12mm-rex-od-12mm-length-12-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1999/images/10934/1520-4012-0120__76024__36775.1701994261.386.513.jpg?c=1', 'MOTION / Shaft Spacers & Shims', 'gobilda'),
  ('8mm REX® Plastic Spacer (12mm REX® OD, 16mm Length) - 12 Pack', '1520-4012-0160', 'This 16mm length, 8mm REX® bore spacer is designed for sliding onto an 8mm REX® shaft to create space between parts. Your choice of spacer length can ensure the correct alignment of drive components, such as gears and sprockets, as well as axially restrain components (such as bearings) to provide for a well-spaced and solid build!', 'goBILDA', null, true, 'https://www.gobilda.com/8mm-rex-plastic-spacer-12mm-rex-od-16mm-length-12-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1650/images/8626/1520-4012-0160__58747__44155.1701993528.386.513.jpg?c=1', 'MOTION / Shaft Spacers & Shims', 'gobilda'),
  ('1521 Series 6mm ID Spacer (8mm OD, 2mm Length) - 4 Pack', '1521-0008-0020', null, 'goBILDA', null, true, 'https://www.gobilda.com/1521-series-6mm-id-spacer-8mm-od-2mm-length-4-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1607/images/8425/1521-0008-0020__98118__54101.1701993461.386.513.jpg?c=1', 'STRUCTURE / Standoffs & Spacers / Spacers / 6mm ID x 8mm OD Spacers', 'gobilda'),
  ('1521 Series 6mm ID Spacer (8mm OD, 4mm Length) - 4 Pack', '1521-0008-0040', null, 'goBILDA', null, true, 'https://www.gobilda.com/1521-series-6mm-id-spacer-8mm-od-4mm-length-4-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1609/images/8429/1521-0008-0040__24507__37250.1701993463.386.513.jpg?c=1', 'STRUCTURE / Standoffs & Spacers / Spacers / 6mm ID x 8mm OD Spacers', 'gobilda'),
  ('1521 Series 6mm ID Spacer (8mm OD, 6mm Length) - 4 Pack', '1521-0008-0060', null, 'goBILDA', null, true, 'https://www.gobilda.com/1521-series-6mm-id-spacer-8mm-od-6mm-length-4-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1863/images/10030/1521-0008-0060__03159__31750.1701993975.386.513.jpg?c=1', 'STRUCTURE / Standoffs & Spacers / Spacers / 6mm ID x 8mm OD Spacers', 'gobilda'),
  ('1521 Series 6mm ID Spacer (8mm OD, 8mm Length) - 4 Pack', '1521-0008-0080', 'This 8mm length, 8mm OD spacer is able to slip over an 6mm shaft—whether that''s a round shaft, D-shaft, or even a lead screw—to create space between components. When you run it against a bearing, the spacer will only contact the bearing''s inner race. This allows your project to rotate smoothly.', 'goBILDA', null, true, 'https://www.gobilda.com/1521-series-6mm-id-spacer-8mm-od-8mm-length-4-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/2033/images/11125/1521-0008-0080__26418__46000.1701994326.386.513.jpg?c=1', 'STRUCTURE / Standoffs & Spacers / Spacers / 6mm ID x 8mm OD Spacers', 'gobilda'),
  ('1521 Series 6mm ID Spacer (8mm OD, 12mm Length) - 4 Pack', '1521-0008-0120', 'This 12mm length, 8mm OD spacer is able to slip over an 6mm shaft—whether that''s a round shaft or a D-shaft—to create space between components. When you run it against a bearing, the spacer will only contact the bearing''s inner race. This allows your project to rotate smoothly.', 'goBILDA', null, true, 'https://www.gobilda.com/1521-series-6mm-id-spacer-8mm-od-12mm-length-4-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/2077/images/11357/1521-0008-0120__36338__34651.1709572227.386.513.jpg?c=1', 'STRUCTURE / Standoffs & Spacers / Spacers / 6mm ID x 8mm OD Spacers', 'gobilda'),
  ('1522 Series 8mm ID Spacer (10mm OD, 2mm Length) - 4 Pack', '1522-0010-0020', null, 'goBILDA', null, true, 'https://www.gobilda.com/1522-series-8mm-id-spacer-10mm-od-2mm-length-4-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1613/images/8439/1522-0010-0020__54330__87136.1701993466.386.513.jpg?c=1', 'STRUCTURE / Standoffs & Spacers / Spacers / 8mm ID x 10mm OD Spacers', 'gobilda'),
  ('1522 Series 8mm ID Spacer (10mm OD, 3mm Length) - 4 Pack', '1522-0010-0030', 'This 3mm length, 10mm OD spacer is able to slip over an 8mm shaft—whether that''s a round shaft, REX shaft, threaded rod, or even a lead screw—to create space between components. When you run it against a bearing, the spacer will only contact the bearing''s inner race. This allows your project to rotate smoothly.', 'goBILDA', null, true, 'https://www.gobilda.com/1522-series-8mm-id-spacer-10mm-od-3mm-length-4-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1894/images/10151/1522-0010-0030___65141__91182.1701994013.386.513.jpg?c=1', 'STRUCTURE / Standoffs & Spacers / Spacers / 8mm ID x 10mm OD Spacers', 'gobilda'),
  ('1522 Series 8mm ID Spacer (10mm OD, 4mm Length) - 4 Pack', '1522-0010-0040', null, 'goBILDA', null, true, 'https://www.gobilda.com/1522-series-8mm-id-spacer-10mm-od-4mm-length-4-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1687/images/8807/1522-0010-0040__36512__79943.1701993586.386.513.jpg?c=1', 'STRUCTURE / Standoffs & Spacers / Spacers / 8mm ID x 10mm OD Spacers', 'gobilda'),
  ('1522 Series 8mm ID Spacer (10mm OD, 6mm Length) - 4 Pack', '1522-0010-0060', 'This 6mm length, 10mm OD spacer is able to slip over an 8mm shaft—whether that''s a round shaft, REX™ shaft, threaded rod, or even a lead screw—to create space between components. When you run it against a bearing, the spacer will only contact the bearing''s inner race. This allows your project to rotate smoothly.', 'goBILDA', null, true, 'https://www.gobilda.com/1522-series-8mm-id-spacer-10mm-od-6mm-length-4-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/2034/images/11130/1522-0010-0060__03318__42966.1701994327.386.513.jpg?c=1', 'STRUCTURE / Standoffs & Spacers / Spacers / 8mm ID x 10mm OD Spacers', 'gobilda'),
  ('1522 Series 8mm ID Spacer (10mm OD, 7mm Length) - 4 Pack', '1522-0010-0070', 'This 7mm length, 10mm OD spacer is able to slip over an 8mm shaft—whether that''s a round shaft, REX shaft, threaded rod, or even a lead screw—to create space between components. When you run it against a bearing, the spacer will only contact the bearing''s inner race. This allows your project to rotate smoothly.', 'goBILDA', null, true, 'https://www.gobilda.com/1522-series-8mm-id-spacer-10mm-od-7mm-length-4-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1895/images/10156/1522-0010-0070__12366__86879.1701994014.386.513.jpg?c=1', 'STRUCTURE / Standoffs & Spacers / Spacers / 8mm ID x 10mm OD Spacers', 'gobilda')
on conflict (btrim(manufacturer), btrim(sku))
